import{_ as a,o as s,c as t,a7 as i}from"./chunks/framework.BJyR0VjM.js";const u=JSON.parse('{"title":"File Structure","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/file-structure.md","filePath":"documentation/file-structure.md"}'),r={name:"documentation/file-structure.md"};function n(l,e,o,c,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="file-structure" tabindex="-1">File Structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to “File Structure”">​</a></h1><p>This page describes all files and directories that YggUtils creates or uses during operation.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/your-server-directory</span></span>
<span class="line"><span>├── YggUtils.jar                 ← the wrapper you run</span></span>
<span class="line"><span>├── YggUtils.yml                 ← configuration file</span></span>
<span class="line"><span>├── YggUtils-server.log          ← appended server output log</span></span>
<span class="line"><span>├── server.jar                   ← your Minecraft server JAR</span></span>
<span class="line"><span>├── meta/</span></span>
<span class="line"><span>│   └── authlibinjector.jar      ← auto-downloaded on first run</span></span>
<span class="line"><span>├── server.properties</span></span>
<span class="line"><span>├── world/</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to “Files”">​</a></h2><h3 id="yggutils-yml" tabindex="-1"><code>YggUtils.yml</code> <a class="header-anchor" href="#yggutils-yml" aria-label="Permalink to “YggUtils.yml”">​</a></h3><p>The configuration file. Generated automatically on first run if missing. Contains <code>authserver</code> and <code>serverfile</code>.</p><p>See <a href="./configuration">Configuration</a> for full details.</p><h3 id="yggutils-server-log" tabindex="-1"><code>YggUtils-server.log</code> <a class="header-anchor" href="#yggutils-server-log" aria-label="Permalink to “YggUtils-server.log”">​</a></h3><p>A plain-text log of all server output. YggUtils appends to this file across sessions — it is never cleared automatically.</p><p>Each line is written exactly as the server produced it, with no additional prefix or timestamp added by the wrapper.</p><p>If you want per-session logs, manually clear or rename this file before starting.</p><h3 id="meta-authlibinjector-jar" tabindex="-1"><code>meta/authlibinjector.jar</code> <a class="header-anchor" href="#meta-authlibinjector-jar" aria-label="Permalink to “meta/authlibinjector.jar”">​</a></h3><p>The authlib-injector Java agent. YggUtils downloads this automatically from the official GitHub release if it is not present.</p><p>If you want to use a specific version, place the JAR here manually before running YggUtils — it will skip the download if the file already exists.</p><h2 id="what-yggutils-does-not-create" tabindex="-1">What YggUtils Does Not Create <a class="header-anchor" href="#what-yggutils-does-not-create" aria-label="Permalink to “What YggUtils Does Not Create”">​</a></h2><p>YggUtils does not create or modify any Minecraft server files. It does not touch <code>server.properties</code>, <code>ops.json</code>, <code>whitelist.json</code>, world data, or any plugin/mod files. All of those remain entirely under the server JAR&#39;s control.</p>`,17)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
